UPDATE questions SET tag3='CS-JJ-01' WHERE id=234368 AND module='changshi';
-- id=234374: 清理广告/页码噪声
UPDATE questions SET explanation='A 项错误，出自陶渊明《桃花源记》，“交通”意为“交错相通”，今义是各种运输和邮电事业的总称；B 项错误，出自曹操《步出夏门行•龟虽寿》，“烈士”意为“志向远大的英雄”，今义是为了正义事业和他人的 生命财产而牺牲自己生命的人；C 项正确，出自诸葛亮《前出师表》，“危急”意为“情况危险紧迫”，与今义 相同，当选；D 项错误，出自《左传》选篇《烛之武退秦师》，“行李”意为“使人、使者”，今义是出门所带 的包裹、物品。 故正确答案为 C。' WHERE id=234374 AND module='changshi';
