UPDATE questions SET question='在“一带一路”国家战略的推动下，中欧班列（长安号）线路发展迅速。该线路从西安出发，开行 14 个国家、44 个城市，实现了欧亚区域全覆盖，目前最远到达：', options='{"A": "巴黎", "B": "巴塞罗那", "C": "罗马", "D": "布鲁塞尔"}' WHERE id=237458 AND module='changshi';
