UPDATE questions SET explanation='向外抽拉针筒推杆，针筒内气体体积增大，压强减小，气球外部气压降低，而气球内部气压不变，内外压强差使气球膨胀，故A正确。B项压强应减小而非不变；C项气球受非平衡力，合力不为零；D项快速抽拉可视为绝热过程，温度降低而非升高。故选A。' WHERE id=246792 AND module='changshi';
