UPDATE questions SET explanation='四灯并联，各灯两端电压恒等于电源电压，故B错误；各灯独立工作，通过每盏灯的电流不变，故A错误；灯亮度由实际功率决定，电压不变则功率不变，故D错误。并联电路中干路电流等于各支路电流之和，灯越多支路越多，干路电流越大，故C正确。故选C。' WHERE id=246793 AND module='changshi';
