UPDATE questions SET explanation='B项出自苏轼《惠州一绝》，罗浮山位于广东，描写岭南四季如春的风物，符合题意。A项黄鹤楼在湖北武汉，C项描绘北方草原景象，D项庐山在江西，均与岭南无关。故选B。' WHERE id=246814 AND module='changshi';
