UPDATE questions SET explanation='D项对应错误，“恸哭六军俱缟素，冲冠一怒为红颜”出自吴伟业《圆圆曲》，写的是吴三桂因陈圆圆被掳而引清兵入关，并非唐玄宗。A项岳飞、B项文天祥、C项诸葛亮均对应正确。故选D。' WHERE id=272842 AND module='changshi';
