UPDATE questions SET tag3='CS-LS-04', explanation='“理财”的“理”意为管理、打理，固定搭配“理财”即管理财务；“财不理你”中的“理”是理睬、搭理的意思，指财富不主动理会人。A项“管理”准确对应“理财”，“理睬”准确对应“不理你”。B项“处理”不如“管理”贴切；C项“搭理”偏口语，且“理财”不适用；D项“料理”侧重具体操办，也不及“管理”恰当。故选A。' WHERE id=286096 AND module='changshi';
