UPDATE questions SET explanation='“善于化危为机”体现了矛盾双方在一定条件下相互转化的哲理。A项“塞翁失马，焉知非福”讲的是祸福在一定条件下可以转化，与之相符。B项“绳锯木断，水滴石穿”强调量变积累引起质变；C项“千里之堤，溃于蚁穴”也是量变引起质变；D项“南橘北枳，便分两等”说明外因对事物影响。故选A。' WHERE id=295222 AND module='changshi';
