UPDATE questions SET explanation='串联电路中电流相等，由P=I²R可知，电阻越大实际功率越大，灯泡越亮。甲灯电阻R甲=U²/P甲=220²/60≈806.7Ω，乙灯电阻R乙=220²/30≈1613.3Ω，乙灯电阻大，故乙灯更亮，A错误。两灯电阻不同，实际功率不同，B错误。串联分压，各灯两端电压均小于220V，不能正常发光，D错误。故选C。' WHERE id=299123 AND module='changshi';
