UPDATE questions SET explanation='冰块漂浮时，其排开水的体积等于冰块熔化成水的体积。根据阿基米德原理，冰的质量等于排开水的质量，而冰熔化成水后质量不变，因此融化后水的体积正好填补了冰排开水的空间，水面高度保持不变。选项A、B、C均不符合物理规律，故选D。' WHERE id=318773 AND module='changshi';
