UPDATE questions SET explanation='冰雹是强对流天气的产物，常伴随雷暴出现。夏季地面受热强烈，空气对流旺盛，易形成发展深厚的积雨云，云中强烈上升气流使冰粒反复升降增大，最终下落成雹。春日的阴雨、秋日的晴朗、冬日的寒冷均缺乏强对流条件。故选B。' WHERE id=318787 AND module='changshi';
