UPDATE questions SET tag3='CS-ZZ-01', explanation='守正创新体现辩证否定观，即事物发展的实质是新事物产生、旧事物灭亡，新事物在旧事物基础上发展。“新竹高于旧竹枝”寓意新事物比旧事物更进步，符合这一哲理。A项“旋岚偃岳而常静”体现绝对运动与相对静止，B项“试玉要烧三日满”强调实践检验，C项“却是平流无石处”说明矛盾转化，均与题意不符。故选D。' WHERE id=896379 AND module='changshi';
