UPDATE questions SET tag3='CS-GL-02', explanation='智慧城市建设遵循从数据汇集到数据使用的逻辑。首先通过电子政务汇集基础数据，其次依托一网通办实现政务服务数据应用，进而利用数字化决策提升治理效能，最终由城市运行中心综合使用数据。故正确顺序为③—②—④—①，干扰项均打乱了数据汇集到使用的递进关系。故选A。' WHERE id=1046578 AND module='changshi';
