UPDATE questions SET tag3='CS-KJ-05', question='下列有关生活常识说法错误的是：', explanation='白糖虽然水分含量少、糖分高，但高渗透压反而能抑制微生物生长，耐储存，故A错误。食醋pH低，酸性环境可抑制微生物，B正确。美白牙膏常含过氧化物，能漂白牙齿，C正确。苹果削皮后变色是酚类氧化反应，属化学变化，影响口感，D正确。故选A。' WHERE id=1046585 AND module='changshi';
