UPDATE questions SET tag3='CS-FL-08', explanation='新条例规定，经营者不得未经消费者同意或默认开通自动续费服务，且应当在续费前显著提示。B选项中“试用期满前五日未取消即视为自动续费”属于默认开通，侵犯消费者知情权和自主选择权，故违反条例。A项符合七日无理由退货规定；C项明确标注爆率及保底，保障知情权；D项提前公告并通知，履行告知义务。故选B。' WHERE id=1046627 AND module='changshi';
